export function getPageForAyah(surahNumber: number, ayahNumber: number): number {
  for (let p = QURAN_PAGE_STARTS.length; p >= 1; p--) {
    const ref = QURAN_PAGE_STARTS[p - 1];
    if (ref.surah < surahNumber || (ref.surah === surahNumber && ref.ayah <= ayahNumber)) {
      return p;
    }
  }
  return 1;
}
